10	  });
11	
12	  test("malformed codes are invalid", () => {
13	    assert.equal(isValidLocode("NL"), false);
14	    assert.throws(() => countryOf("12345"), RangeError);
15	  });
16	
17	  test("country", () => {
18	    assert.equal(countryOf("DEHAM"), "DE");
19	  });
20	});
21	
22	describe("registry", () => {
23	  test("ports by code", () => {
24	    assert.equal(portByCode("nlrtm")?.name, "Rotterdam");
25	    assert.equal(portByCode("XXZZZ"), undefined);
26	  });
27	
28	  test("ports by country", () => {
29	    assert.deepEqual(portsInCountry("us").map((p) => p.code), ["USLAX", "USNYC"]);
30	  });
